"use strict";
class ItemImpl {
  constructor(name, count, level) {
    this.name = name;
    this.count = count;
    this.nested = { level };
  }
  label() {
    return this.name + "#" + this.count;
  }
}
let current = null;
const make = (name) => (current = new ItemImpl(name, 1, 2));
const all = () => [current, exports.shared, exports.holder.item].filter(Boolean);
exports.shared = new ItemImpl("shared", 10, 5);
exports.holder = { item: new ItemImpl("held", 20, 7) };
exports.make = make;
exports.later = (name) => Promise.resolve(make(name));
exports.each = (fn) => fn(make("each"));
exports.raw = (name) => make(name);
exports.take = (name) => make(name);
exports.bump = () => {
  for (const item of all()) {
    item.count += 100;
    item.nested.level += 1;
  }
};
exports.same = (value) => all().includes(value);
exports.peek = () => all().map((item) => item.name + ":" + item.count + ":" + item.nested.level).join(" ");
exports.read = (value) => value.name + ":" + value.count + ":" + value.nested.level + ":" + typeof value.label;
